Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest()")

	$$$TRACE("Access Token: "_pRequest.accessToken) 


	Set httprequest=##class(%Net.HttpRequest).%New()
	set httprequest.Timeout=..Adapter.ResponseTimeout
	Set httprequest.ContentType="application/json"
	Set httprequest.SSLConfiguration = ..Adapter.SSLConfig
	set url = ..Adapter.URL
	Set httprequest.Location = url
	$$$TRACE("Location: "_httprequest.Location)
	Set jsonRequest = "{""finNumber"": """_pRequest.encounterId_""", ""scheduleID"": """_pRequest.apptId_"""}" 
	$$$TRACE(" JSONRequest: "_jsonRequest)  
	Do httprequest.EntityBody.Write(jsonRequest) 

	set sc=##class(%SYS.OAuth2.AccessToken).AuthorizeWithAccessToken(httprequest,"header",..Adapter.SSLConfig,"PingSecurityToken",pRequest.accessToken)
	$$$TRACE("Token status (Add) "_sc)
	Set pResponse=##class(Ens.StringResponse).%New()
	Set mylist = ##class(%Collection.ArrayOfObj).%New()
	try	{
		set getStatus = httprequest.Get(url)				
		set getStatusTxt = $SYSTEM.Status.GetOneErrorText(getStatus)	    	
		$$$TRACE("Get service Status(Add):  "_getStatusTxt)
		Set writer=##class(%Net.MIMEWriter).%New()
        Set status=writer.OutputToStream(httprequest.EntityBody)
        set len = httprequest.HttpResponse.ContentLength     
    	set respData = httprequest.HttpResponse.Data.Read()
    	$$$TRACE("RESP DATA11 ???? "_respData) 
    	if (respData [ "Authorization failed"){
	    	set tSC=##class(IHC.ITF.ITFCOMMON.Utility).InputDataError("Op-IhcHie-Wsrc-FACILITYALIAS"," ERRTOKEN. Invalid or Expired access token.  Response: "_respData) 
    	}else{
			if (getStatus =1){
				$$$TRACE(" AmWell Encounter Service..Get Operation OK")  
	            set response=httprequest.HttpResponse        
       			$$$TRACE("StatusLine: "_response.StatusLine) 
       			set statusLine = response.StatusLine 
       			set statusCode = ""
       			set statusDesc = ""
       			if (statusLine'=""){
					set statusCode=$piece(statusLine," ",2)
					set statusDesc=$piece(statusLine," ",3)			
      			}      
      			$$$TRACE("StatusCode: "_statusCode)  	     
      			$$$TRACE("StatusDesc: "_statusDesc)  	         	
    			if (statusCode'="200"){
	    			$$$TRACE("  DisableMsgError.... ")
          			set tSC=##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-IhcHie-Wsrc-FACILITYALIAS"," Response from AmWell Encounter Service Get Operation: "_respData) 
			    }else{
				   set consumedJSONobj = ##class(%DynamicAbstractObject).%FromJSON(respData)
        		   set statusVal = ((consumedJSONobj.%Get("data")).%Get("response").%Get("service-status")).%Get("status")  
        		   $$$TRACE("  statusVal: "_statusVal)     
      			   if (statusVal="SUCCESS"){
	      			   set codeValueAlias = ((consumedJSONobj.%Get("data")).%Get("response").%Get("status-details")).%Get("CODE_VALUE_ALIAS") 
	      			   set locFacilityCd = ((consumedJSONobj.%Get("data")).%Get("response").%Get("status-details")).%Get("LOC_FACILITY_CD") 
	      			   Set pResponse.StringValue = codeValueAlias_"|"_locFacilityCd
	      			    $$$TRACE("  codeValueAlias|LocFacilityCd:" _pResponse.StringValue)  
      			   }else{
	      			   set errStatusMsg = ((consumedJSONobj.%Get("data")).%Get("response").%Get("service-status")).%Get("message") 
	      			   Set pResponse.StringValue = errStatusMsg	      			   
	      		   }	      	    
				}		  	
        	} else {
          		$$$TRACE("AmWell Encounter call status 200 OK !!! :")          		        		

        	}
		}
	}catch e{
		 	$$$TRACE(" Unknown Exception: " _ e)
		 	set errTxt = $System.Status.GetErrorText("Unknown Exception while calling AmWell encounter service GET operation "_e)		 
		 	Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-IhcHie-Wsrc-FACILITYALIAS",errTxt)	  		 		  		 		 
		}

	Quit tSC
